<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const {data:settings,refresh}=await useFetch<any>('/api/admin/settings')
const form=ref<any>({}),saving=ref(false),error=ref(''),notice=ref('')
watch(settings,v=>{if(v)form.value=JSON.parse(JSON.stringify(v))},{immediate:true})
const fields=[{key:'doctor_name',title:'نام پزشک',placeholder:'دکتر آزاده مهرداد'},{key:'tagline',title:'شعار کوتاه سایت',placeholder:'لبخند زیبا، آغاز اعتمادبه‌نفس شما'},{key:'phone',title:'شماره تماس مطب',placeholder:'مثلاً: 021xxxxxxxx'},{key:'address',title:'آدرس دقیق مطب',placeholder:'شهر، خیابان، پلاک، واحد'},{key:'map_url',title:'لینک مسیریابی Google Maps یا نشان',placeholder:'https://...'},{key:'instagram_url',title:'لینک اینستاگرام',placeholder:'https://instagram.com/...'},{key:'doctor_photo',title:'لینک تصویر واقعی پزشک',placeholder:'https://...'},{key:'hero_photo',title:'آدرس تصویر بالای صفحه',placeholder:'/images/smile-hero.webp'}]
async function save(){saving.value=true;error.value='';notice.value='';try{await $fetch('/api/admin/settings',{method:'PUT',body:form.value});await refresh();await refreshNuxtData('public-site');notice.value='تنظیمات مطب با موفقیت ذخیره شد.'}catch(e){error.value=humanError(e)}finally{saving.value=false}}
useSeoMeta({title:'تنظیمات سایت و مطب | مدیریت',robots:'noindex,nofollow'})
</script>
<template><div><div class="mb-8"><span class="eyebrow">شخصی‌سازی وب‌سایت</span><h1 class="text-3xl font-extrabold mt-2 text-jade-800">اطلاعات و تنظیمات مطب</h1><p class="text-xs text-[#879d8f] mt-2">فیلدهای تکمیل‌نشده در سایت با برچسب مشخص نشان داده می‌شوند.</p></div><div v-if="settings" class="max-w-[900px]"><p v-if="error" class="bg-red-50 rounded-xl p-4 text-red-700 text-xs mb-4" role="alert">{{error}}</p><p v-if="notice" class="bg-green-50 rounded-xl p-4 text-green-700 text-xs mb-4">{{notice}}</p><form class="space-y-6" @submit.prevent="save"><div class="glass-card p-7 sm:p-9"><h2 class="font-bold text-jade-800 mb-7 flex gap-2 items-center"><Icon name="user-round" :size="20" /> معرفی و اطلاعات پزشک</h2><div class="grid sm:grid-cols-2 gap-5"><div v-for="field in fields" :key="field.key" :class="field.key==='address'?'sm:col-span-2':''"><label class="field-label">{{field.title}}</label><input v-model="form[field.key]" class="input-field" :placeholder="field.placeholder" /></div><div class="sm:col-span-2"><label class="field-label">متن معرفی صفحه اصلی</label><textarea v-model="form.intro" class="input-field" rows="3" maxlength="1500"></textarea></div><div class="sm:col-span-2"><label class="field-label">بیوگرافی</label><textarea v-model="form.biography" class="input-field" rows="4" maxlength="5000" placeholder="صرفاً اطلاعات تأییدشده پزشک را وارد کنید."></textarea></div><div class="sm:col-span-2"><label class="field-label">تحصیلات و سوابق</label><textarea v-model="form.education" class="input-field" rows="3" maxlength="2500"></textarea></div><div class="sm:col-span-2"><label class="field-label">مدارک و گواهی‌ها</label><textarea v-model="form.certificates" class="input-field" rows="3" maxlength="2500"></textarea></div></div></div><div class="glass-card p-7 sm:p-9"><h2 class="font-bold text-jade-800 mb-7 flex gap-2 items-center"><Icon name="settings" :size="20" /> قوانین رزرو</h2><div class="grid sm:grid-cols-2 gap-5"><div><label class="field-label">حداقل ساعت لازم تا لغو یا تغییر نوبت</label><input v-model.number="form.cancellation_hours" type="number" min="0" max="168" class="input-field" /></div><div><label class="field-label">بازه روزهای قابل رزرو در آینده</label><input v-model.number="form.booking_horizon_days" type="number" min="7" max="365" class="input-field" /></div><div><label class="field-label">فاصله شروع نوبت‌ها (دقیقه)</label><select v-model.number="form.slot_step_minutes" class="input-field"><option v-for="n in [5,10,15,20,30,60]" :key="n" :value="n">{{faNumber(n)}} دقیقه</option></select></div><div><label class="field-label">منطقه زمانی (IANA)</label><input v-model="form.timezone" class="input-field" dir="ltr" placeholder="Asia/Tehran" /></div></div><div class="bg-[#f4f9f5] border border-[#e3eee6] p-5 rounded-2xl mt-6 flex gap-3"><input v-model="form.deposit_enabled" type="checkbox" class="accent-[#0b5349] self-start mt-1" disabled /><div><p class="text-sm font-bold text-jade-800">پرداخت بیعانه (آماده برای توسعه بعدی)</p><p class="text-xs text-[#819a8b] leading-8 mt-1">درگاه پرداخت هنوز متصل نشده است؛ فعال‌سازی این گزینه تا پیاده‌سازی پرداخت واقعی غیرفعال است.</p></div></div></div><div class="flex gap-3"><button class="btn-main !px-9" :disabled="saving"><Icon :name="saving?'loader-circle':'check-circle-2'" :size="18" /> {{saving?'در حال ذخیره...':'ذخیره تمام تغییرات'}}</button><NuxtLink to="/" class="btn-light">مشاهده سایت</NuxtLink></div></form></div><p v-else class="text-xs text-red-700">دریافت تنظیمات از سرور انجام نشد.</p></div></template>
